      "linha_tempo": "<div style='border-left:3px solid #6366f1;margin-left:14px;padding-top:6px;'><div style='position:relative;padding-left:28px;padding-bottom:16px;'><div style='position:absolute;left:-9px;top:6px;width:16px;height:16px;border-radius:50%;background:#818cf8;border:3px solid #1e1b4b;'></div><div style='background:#1e293b;border:1px solid #334155;padding:14px 18px;border-radius:12px;color:#f1f5f9;line-height:1.68;'>Origem e fundamentos iniciais de Romantismo nas Artes Visuais</div></div><div style='position:relative;padding-left:28px;padding-bottom:16px;'><div style='position:absolute;left:-9px;top:6px;width:16px;height:16px;border-radius:50%;background:#818cf8;border:3px solid #1e1b4b;'></div><div style='background:#1e293b;border:1px solid #334155;padding:14px 18px;border-radius:12px;color:#f1f5f9;line-height:1.68;'>Consolidação teórica em ARTE</div></div><div style='position:relative;padding-left:28px;padding-bottom:16px;'><div style='position:absolute;left:-9px;top:6px;width:16px;height:16px;border-radius:50%;background:#818cf8;border:3px solid #1e1b4b;'></div><div style='background:#1e293b;border:1px solid #334155;padding:14px 18px;border-radius:12px;color:#f1f5f9;line-height:1.68;'>Aplicações modernas e cobrança no ENEM</div></div></div>",
      "tabela_comparativa": "<div style='max-width:74ch;color:#f1f5f9;font-size:1.02rem;line-height:1.78;letter-spacing:0.015em;word-spacing:0.04em;'><div style='overflow-x:auto;margin:14px 0;'><table style='width:100%;border-collapse:collapse;background:#1e293b;color:#f1f5f9;border-radius:12px;overflow:hidden;border:1px solid #334155;'><thead><tr style='background:#312e81;color:#e0e7ff;'>\n<th style='padding:12px 16px;text-align:left;font-weight:700;'>Aspecto</th>\n<th style='padding:12px 16px;text-align:left;font-weight:700;'>Característica em Romantismo nas Artes Visuais</th>\n</tr></thead><tbody>\n<tr style='border-bottom:1px solid #334155;'>\n<td style='padding:12px 16px;line-height:1.6;'>Conceito-Chave</td>\n<td style='padding:12px 16px;line-height:1.6;'>Estrutura central de ARTE</td>\n</tr>\n<tr style='border-bottom:1px solid #334155;'>\n<td style='padding:12px 16px;line-height:1.6;'>Aplicação</td>\n<td style='padding:12px 16px;line-height:1.6;'>Resolução de problemas (2EM)</td>\n</tr>\n</tbody></table></div></div>",
